package com.shale.data.service.adapter;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import com.shale.core.dto.UserSessionView;import com.shale.core.model.ClientType;
class UserSessionServiceAdapterTest{
	private static final Instant NOW=Instant.parse("2026-09-29T12:00:00Z");
	@Test void createsRandomStableIdentifierAndPreservesServerScope(){Gateway g=new Gateway();var a=new UserSessionServiceAdapter(g,Clock.fixed(NOW,ZoneOffset.UTC));UUID j=UUID.randomUUID();var one=a.create(7,9,ClientType.DESKTOP,5L,j,NOW.plusSeconds(60));var two=a.create(7,9,ClientType.WEB,null,UUID.randomUUID(),NOW.plusSeconds(60));assertNotEquals(one.sessionId(),two.sessionId());assertEquals(7,g.tenant);assertEquals(9,g.user);assertEquals(j,one.currentAccessJti());assertThrows(IllegalArgumentException.class,()->a.create(7,9,ClientType.MOBILE,5L,j,NOW.plusSeconds(60)));}
	@Test void validatesExpiryReasonsAndCredentialRotation(){Gateway g=new Gateway();var a=new UserSessionServiceAdapter(g,Clock.fixed(NOW,ZoneOffset.UTC));UUID old=UUID.randomUUID(),next=UUID.randomUUID(),sid=a.create(7,9,ClientType.WEB,null,old,NOW.plusSeconds(60)).sessionId();assertThrows(IllegalArgumentException.class,()->a.create(7,9,ClientType.WEB,null,old,NOW));assertThrows(IllegalArgumentException.class,()->a.revoke(7,9,sid,"PROSE"));assertEquals(next,a.rotateAccessCredential(7,9,sid,old,next,NOW.plusSeconds(120)).currentAccessJti());}
	@Test void revocationIsIdempotentAndFirstReasonAndTimestampSurvive(){Gateway g=new Gateway();var a=new UserSessionServiceAdapter(g,Clock.fixed(NOW,ZoneOffset.UTC));UUID sid=a.create(7,9,ClientType.WEB,null,UUID.randomUUID(),NOW.plusSeconds(60)).sessionId();var first=a.revoke(7,9,sid,"SECURITY");var again=a.revoke(7,9,sid,"USER_LOGOUT");assertEquals(first.revokedAt(),again.revokedAt());assertEquals("SECURITY",again.revocationReason());assertFalse(again.isActive(NOW));}
	static final class Gateway implements UserSessionServiceAdapter.Gateway{int tenant,user;UserSessionView value;public UserSessionView create(int t,int u,ClientType c,Long i,UUID s,UUID j,Instant e){tenant=t;user=u;return value=new UserSessionView(1,s,c,i,j,NOW,e,null,null,null);}public Optional<UserSessionView> find(int t,int u,UUID s){return Optional.ofNullable(value);}public UserSessionView revoke(int t,int u,UUID s,String r){if(value.revokedAt()==null)value=new UserSessionView(value.id(),s,value.clientType(),value.applicationInstanceId(),value.currentAccessJti(),value.issuedAt(),value.expiresAt(),value.lastRefreshedAt(),NOW,r);return value;}public UserSessionView rotate(int t,int u,UUID s,UUID x,UUID n,Instant e){if(!value.currentAccessJti().equals(x)||value.revokedAt()!=null)throw new IllegalStateException();return value=new UserSessionView(value.id(),s,value.clientType(),value.applicationInstanceId(),n,value.issuedAt(),e,NOW,null,null);}}
}
